import{az as l,P as a,Q as e,aQ as r,bH as t,bI as n}from"./chunks/framework.oHSDCGnP.js";import"./chunks/theme.SRuXo2Mz.js";const S=JSON.parse('{"title":"王刚 - 前端开发工程师","description":"","frontmatter":{},"headers":[],"relativePath":"其他/简历.md","filePath":"其他/简历.md","lastUpdated":1785133858000}'),o={name:"其他/简历.md"};function s(h,i,g,d,c,p){return a(),e("div",null,[...i[0]||(i[0]=[r('<h1 id="王刚-前端开发工程师" tabindex="-1">王刚 - 前端开发工程师 <a class="header-anchor" href="#王刚-前端开发工程师" aria-label="Permalink to “王刚 - 前端开发工程师”">​</a></h1><p>6年前端开发经验 / 男 / 28岁 / 籍贯河北 / 现居北京 / 离职-随时到岗</p><p><img src="'+t+'" alt="tel" width="20" height="20" style="vertical-align:middle;margin-right:.3rem;display:inline-block;">17600980516</p><p><img src="'+n+'" alt="email" width="20" height="20" style="vertical-align:middle;margin-right:.3rem;display:inline-block;"><a href="mailto:17600980516@163.com" target="_blank" rel="noreferrer">17600980516@163.com</a></p><h2 id="个人简介" tabindex="-1">个人简介 <a class="header-anchor" href="#个人简介" aria-label="Permalink to “个人简介”">​</a></h2><p>能快速对接产品需求、前后端工作，具有从需求分析、架构设计到开发交付与上线运维的全流程前端能力。具备稳定性与性能优化经验，能有效提升团队交付效率与产品落地速度。</p><p>熟悉 <strong>Vue 2/3、React、Next.js、Nuxt.js、uni-app、TypeScript</strong> 等主流技术栈，具备 <strong>后台管理系统、H5、微信小程序、SSR 服务端渲染</strong> 等项目实战经验。主导过 <strong>无代码/低代码可视化搭建平台</strong> 从 0 到 1 落地，参与 <strong>金融科技类多资产交易平台</strong> 开发。</p><p>熟悉 <strong>Webpack/Vite 工程化、Git、Docker、Jenkins、GitHub Actions、CI/CD 自动化部署</strong>，具备 <strong>WebSocket 实时通信、性能优化、Sentry 监控、i18n 国际化、SEO</strong> 等实践经验，独立承担需求分析、开发交付全流程工作。</p><p>熟练运用 <strong>Cursor、AI Agent</strong> 等进行 <strong>Vibe Coding</strong>，擅长通过 Prompt 拆解需求、Agent 协作落地与人工 Code Review 闭环，在保证业务正确性与工程质量的前提下显著提升交付效率；了解 <strong>MCP、RAG、Skill</strong> 等 AI 工程化能力，能将 AI 融入日常开发与文档沉淀。</p><h2 id="技术栈" tabindex="-1">技术栈 <a class="header-anchor" href="#技术栈" aria-label="Permalink to “技术栈”">​</a></h2><ul><li>语言：HTML5、CSS3、JavaScript(ES6+)、TypeScript</li><li>框架：Vue 2/3、Nuxt.js、React、Next.js、uni-app、小程序</li><li>状态管理与 UI：Pinia、Vuex、Redux、Element Plus、Ant Design、Tailwind CSS、SCSS</li><li>工程化：Vite、Webpack、Babel、ESLint、Prettier、Husky、Commitizen、Monorepo</li><li>网络与协作：Axios、RESTful API、WebSocket、Node.js、Express、Koa</li><li>部署与运维：Git、Docker、Jenkins、GitHub Actions、PM2、CI/CD、多环境自动化发版</li><li>专项能力：低代码/无代码平台、后台管理系统、SSR、性能调优、首屏/首包优化、SEO、i18n 国际化、Sentry 监控</li><li>Vibe Coding / AI 辅助开发（Cursor、Agent、Prompt）</li></ul><h2 id="工作经历" tabindex="-1">工作经历 <a class="header-anchor" href="#工作经历" aria-label="Permalink to “工作经历”">​</a></h2><h3 id="北京海利普科贸有限公司-2025-05-2025-11" tabindex="-1">北京海利普科贸有限公司 ／ 2025.05 - 2025.11 <a class="header-anchor" href="#北京海利普科贸有限公司-2025-05-2025-11" aria-label="Permalink to “北京海利普科贸有限公司 ／ 2025.05 - 2025.11”">​</a></h3><h4 id="biyapay-多资产综合交易平台-react-next-js-typescript" tabindex="-1">BiyaPay 多资产综合交易平台（React + Next.js + TypeScript） <a class="header-anchor" href="#biyapay-多资产综合交易平台-react-next-js-typescript" aria-label="Permalink to “BiyaPay 多资产综合交易平台（React + Next.js + TypeScript）”">​</a></h4><h5 id="业务场景" tabindex="-1">业务场景 <a class="header-anchor" href="#业务场景" aria-label="Permalink to “业务场景”">​</a></h5><ul><li>面向全球用户的多资产综合交易平台建设，覆盖资产管理、跨境汇款、数字资产交易、美港股投资等高度复杂的金融场景，属于典型的高复杂度、强实时性、强合规性业务系统</li><li>项目涉及钱包、收付款、币种兑换、资金流转、多资产交易、用户认证等多条核心流程，需同时支撑多币种、多地区、多终端的用户访问与体验</li></ul><h5 id="技术亮点" tabindex="-1">技术亮点 <a class="header-anchor" href="#技术亮点" aria-label="Permalink to “技术亮点”">​</a></h5><ul><li>基于 Next.js 13 + React 18 + Ant Design 5 + Tailwind CSS 构建 SSR 页面体系，参与前端架构维护与模块拆分，持续优化组件设计、状态管理与工程化组织，提升项目整体可维护性与开发效率</li><li><strong>国际化（i18n）</strong>: 基于 next-i18next 实现中英双语，SSR 服务端翻译 + Cookie 语言持久化，Ant Design + dayjs 国际化联动</li><li><strong>暗黑/浅色主题</strong>: 通过 CSS 变量 + Ant Design ConfigProvider 实现全局主题切换，同步适配 TradingView 图表主题</li><li><strong>响应式布局</strong>: 桌面与移动端功能展示一致</li><li>接入埋点、Sentry 全链路错误监控</li><li>负责前端性能与稳定性优化，覆盖首屏渲染、接口请求、组件复用、状态管理与异常兜底，显著降低页面卡顿、数据异常与线上故障风险</li><li>负责 WebSocket 实时行情与资产/订单推送链路的前端实现，覆盖订阅管理、心跳保活、断线重连、节流处理、页面可见性控制等关键机制，保障高频实时数据在复杂交易场景下的稳定性与体验</li><li>使用 decimal.js 解决金融运算精度问题（保证金、手续费、盈亏、汇率、转账手续费等）</li><li>使用 PM2 管理进程，Docker 容器化，支持多环境部署（本地/开发/预发布/生产）</li></ul><h5 id="主要负责开发功能模块" tabindex="-1">主要负责开发功能模块 <a class="header-anchor" href="#主要负责开发功能模块" aria-label="Permalink to “主要负责开发功能模块”">​</a></h5><ol><li><p>钱包资金账户</p><ul><li>包含美港股、现货、期货、合约的资金账户，每个账户模块包含资产估值、持仓信息、账单、闪兑、划转、充值、订单等功能</li><li>使用 WebSocket 实时更新资产和持仓，下单、撤单、订单成交、持仓变化、收益变化、保证金率变化、资产余额变动均实时同步</li><li>交易账单记录及详情：市场交易、账户划转、法币/数字货币/稳定币兑换、链上充值/提现、银行账户充值/汇款、邮箱收款/充值/转账</li><li>支持限价单、市价单、止盈止损单、追踪止损单等多种订单类型，订单分享引流</li></ul></li><li><p>资金管理</p><ul><li><strong>链上充提</strong>: 支持多链网络充值/提现</li><li><strong>法币跨境汇款</strong>: 银行账户充值、银行账户汇款</li><li><strong>内部转账</strong>: 站内资金账户划转</li><li><strong>邮件收款</strong>: 邮箱收款、充值、转账</li><li><strong>闪兑</strong>: 法币、数字货币、稳定币的兑换，实时汇率更新</li><li><strong>支付账户</strong>: 创建/管理多币种支付账户，收款人管理、地址管理（链上充提）</li></ul></li><li><p>多资产交易（6 大交易品种）</p><ul><li>加密货币现货、永续合约、美股、港股、美股期权、港股期权</li><li>限价/市价/止损限价/止盈限价/OCO 订单（双向止盈止损）/条件单/计划委托</li><li>杠杆设置、止盈止损、持仓管理、强平价格计算</li><li>通过 WebSocket 实时推送行情、订单成交、持仓变更</li></ul></li><li><p>账户安全</p><ul><li><strong>身份认证（KYC）</strong>: 身份证/护照认证、证件照片上传、人脸识别（活体检测）、审核进度与驳回重提交</li><li><strong>安全设置</strong>: AML 反洗钱验证，补充材料上传</li></ul></li><li><p>模拟交易账户</p><ul><li>将交易模块和账户资金模块组件化，通过接口切换复用整套模块支撑模拟交易</li><li>全屏无头尾布局，与真实交易页面风格一致</li></ul></li></ol><hr><h3 id="东易日盛家居装饰集团股份有限公司-2021-07-2025-03" tabindex="-1">东易日盛家居装饰集团股份有限公司 ／ 2021.07 - 2025.03 <a class="header-anchor" href="#东易日盛家居装饰集团股份有限公司-2021-07-2025-03" aria-label="Permalink to “东易日盛家居装饰集团股份有限公司 ／ 2021.07 - 2025.03”">​</a></h3><h4 id="无代码-低代码可视化搭建平台-vue3-vite-从-0-到-1-主导开发" tabindex="-1">无代码/低代码可视化搭建平台（Vue3 + Vite，从 0 到 1 主导开发） <a class="header-anchor" href="#无代码-低代码可视化搭建平台-vue3-vite-从-0-到-1-主导开发" aria-label="Permalink to “无代码/低代码可视化搭建平台（Vue3 + Vite，从 0 到 1 主导开发）”">​</a></h4><p>DEMO <a href="https://wangguanl.github.io/page__lego/" target="_blank" rel="noreferrer">https://wangguanl.github.io/page__lego/</a></p><h5 id="业务场景-1" tabindex="-1">业务场景 <a class="header-anchor" href="#业务场景-1" aria-label="Permalink to “业务场景”">​</a></h5><p>29 家子公司每天产出专题设计图提交到总部，由开发人员做成运营活动页、落地页、专题页面再交付给子公司。总部拿到设计图进行运营和设计师的审核，审核通过后再排期制作，审核不通过则再沟通设计图错误并返回修改再如此反复。大量的页面开发占用了50%的开发资源，导致了人手紧缺、重复开发、沟通效率低等问题，则开发了无代码搭建平台，减少对开发团队的强依赖。</p><h5 id="功能介绍" tabindex="-1">功能介绍 <a class="header-anchor" href="#功能介绍" aria-label="Permalink to “功能介绍”">​</a></h5><p>无代码平台通过可视化拖拽操作 + 行业化模板库 + 融合物料体系，实现从需求到上线的全流程敏捷交付。将繁琐的底层架构和基础设施抽象化为图形界面，免去了代码编写工作，能够完全专注于业务场景。</p><h5 id="技术栈-1" tabindex="-1">技术栈 <a class="header-anchor" href="#技术栈-1" aria-label="Permalink to “技术栈”">​</a></h5><ul><li>独立完成产品设计、前端架构、技术选型、功能开发与优化。</li><li>前端架构基于 Vite + Vue3 + Pinia + Element Plus</li><li>改良 draggable-resizable、draggable-sortable 实现组件在画布上的缩放与拖拽</li><li>集成 Ace Editor、Highlight.js、Prettier、Monaco Editor 实现在线代码编辑与语法高亮</li></ul><h5 id="核心功能" tabindex="-1">核心功能 <a class="header-anchor" href="#核心功能" aria-label="Permalink to “核心功能”">​</a></h5><ul><li>可视化页面编辑器，覆盖页面构建、样式配置、交互管理与导出流程，<strong>所见即所得</strong></li><li>支持SEO，可自主编写SEO标题、搜索词、关键字</li><li>设计通用组件库，建立前端规范体系</li><li>拖拽画布、组件属性编辑、样式面板</li><li>支持可视化 CSS 样式配置、动画设置、事件与交互面板</li><li>设计 JSON Schema 驱动渲染，使用编译/反编译引擎 进行导入解析HTML，也可以导出HTML/CSS。并且可以使用 JSON Schema 配合引擎进行服务端渲染，可编辑代码。</li><li>产出优化：图片懒加载、CDN优化</li><li>支持PC、H5双端，可自适配</li></ul><h5 id="业务价值" tabindex="-1">业务价值 <a class="header-anchor" href="#业务价值" aria-label="Permalink to “业务价值”">​</a></h5><ul><li><strong>缩短业务周期</strong>：减少制作流程，专题页面交付周期从 <strong>2天</strong> 缩短至 <strong>2~3小时</strong>，覆盖公司 95% 运营活动需求。</li><li><strong>极速交付</strong>：具有时效的专题不会因为排期等问题而错过档期。</li><li><strong>减少开发人力成本</strong>：使非专业开发人员也能参与到应用开发中，减少了对专业程序员的依赖，从而降低了开发人力成本。同时，由于开发效率的提高，也减少了项目开发过程中的人力投入和时间成本。</li><li><strong>降低技术维护成本</strong>：无代码平台生成的页面有较高的稳定性和可维护性，减少了因代码的不规范、复杂、质量不高导致的维护成本。而且方便对已生成的页面进行更新、升级和故障排查，降低了技术维护的难度和成本。</li><li><strong>提升转化</strong>：在生成的页面中埋点收集用户行为，通过页面停留时长、点击、浏览、滑动等行为偏好分析发现用户流失节点，推动改版后留存率提升。</li><li><strong>提升团队价值</strong>：让开发团队由典型的 <strong>成本导向型</strong> 转型 <strong>价值输出型</strong></li></ul><hr><h4 id="微信小程序-uni-app-跨端开发" tabindex="-1">微信小程序 / uni-app 跨端开发 <a class="header-anchor" href="#微信小程序-uni-app-跨端开发" aria-label="Permalink to “微信小程序 / uni-app 跨端开发”">​</a></h4><ol><li>实现 uni-app 框架底层渐进式升级，一套代码产出微信、百度、头条三端小程序，保障跨端开发效率与稳定性。</li><li>通过组件化拆分 + CDN静态资源托管，总包体积由 <strong>2.1MB</strong> 压缩至 <strong>1.4MB</strong> ，体积降低 <strong>33%</strong>。</li><li>小程序<strong>首次</strong> 打开访问速度，由 <strong>4~5</strong> 秒减少至 <strong>1~2</strong> 秒，性能评估报告由 <strong>43%</strong> 提升至 <strong>96%</strong>，<strong>减少用户等待时间，有效提升客户转化</strong>。</li><li>搭建 CI 一键发版工具，支撑 29 个城市分公司自动化发版，建立开发/测试/预生产/生产多环境发布流程。</li></ol><hr><h4 id="app内嵌h5" tabindex="-1">APP内嵌H5 <a class="header-anchor" href="#app内嵌h5" aria-label="Permalink to “APP内嵌H5”">​</a></h4><ul><li>升级脚手架并拆分本地开发、测试、预生产、正式生产环境，降低环境配置错误风险</li><li>配合运维搭建 Jenkins 一键上线流程，提升发布效率与稳定性</li><li>新增 vConsole 调试入口，快速定位线上问题，加速 Bug 修复</li></ul><hr><h4 id="团队规范与文档建设" tabindex="-1">团队规范与文档建设 <a class="header-anchor" href="#团队规范与文档建设" aria-label="Permalink to “团队规范与文档建设”">​</a></h4><ul><li>推动 ESLint + Prettier 统一代码规范，使用 Commitizen + Husky 强制提交规范</li><li>完成项目文档沉淀，包括项目简介、软件定位，软件的基本功能、技术栈说明、目录结构、启动流程与常见问题</li></ul><hr><h3 id="北京亿特诺美电子商务有限公司-2020-04-2021-07" tabindex="-1">北京亿特诺美电子商务有限公司 ／ 2020.04 - 2021.07 <a class="header-anchor" href="#北京亿特诺美电子商务有限公司-2020-04-2021-07" aria-label="Permalink to “北京亿特诺美电子商务有限公司 ／ 2020.04 - 2021.07”">​</a></h3><ul><li>主导 Vue 老旧项目重构与 Webpack 脚手架升级，提升开发效率与构建速度</li><li>配置 Mock 环境与 Proxy 代理，优化前后端分离开发调试体验</li><li>引入全局 SCSS 规范与组件封装，提升样式复用与代码可维护性</li><li>通过 chainWebpack 优化构建配置，缩短打包时间并提升 CI/CD 发布效率</li><li>处理移动端 H5、微信浏览器兼容性问题，防抖/节流优化页面交互性能</li></ul><h3 id="北京戴纳科技有限公司-2018-07-2020-03" tabindex="-1">北京戴纳科技有限公司 ／ 2018.07 - 2020.03 <a class="header-anchor" href="#北京戴纳科技有限公司-2018-07-2020-03" aria-label="Permalink to “北京戴纳科技有限公司 ／ 2018.07 - 2020.03”">​</a></h3><ul><li>参与 Web 端 ERP 后台管理系统需求分析、设计、前端编码、测试与上线</li><li>负责 ERP 系统前端优化与重构，提升系统稳定性与运行可靠性</li><li>参与项目版本迭代、维护与 Webpack 打包上线，保证交付质量</li></ul>',48)])])}const m=l(o,[["render",s]]);export{S as __pageData,m as default};
